"""Independent v2 motion candidates, explicitly authorized for visual review."""
from pathlib import Path
import json

ROOT=Path(__file__).resolve().parents[1]
XI=ROOT/'Art/NPCs/xiya/v2'
QI=ROOT/'Art/Companions/qibei/v2'


def main():
    xiya='SAME Xiya as references: violet/lavender long side-parted hair, blue eyes, small folded green cap, short green tunic/shoulder sleeves with black neckline and rectangular gold chest clasp, vivid magenta waist sash, black sleeves/lower trousers and green boots. Same face, body proportions, garment panels, hair length and cap position. No sword or other props baked into body. Two arms, two legs, no duplicate hands.'
    qibei='SAME Qibei: round pink legless spirit, curled crown tuft, ONE PAIR of matching pink two-lobed wings on both sides. Field face has BLACK sleepy horizontal eyes, yellow-green oval cheeks and small rose/red mouth. No feet, arms, cat ears, muzzle or blue wings. Core body and facial positions stay constant; wings pivot from fixed attachments, never detach or change anatomy.'
    walk='Six chronological poses of ONE full walking cycle: 0 anatomical LEFT foot forward/right foot back, RIGHT arm forward; 1 weight on left flat foot, right heel lifts; 2 right leg passes forward while left supports, arms passing center; 3 RIGHT foot forward/left back, LEFT arm forward; 4 weight on right flat foot, left heel lifts; 5 left leg passes forward while right supports. Feet alternately contact and pass, not six copies of the same leading leg. Small torso weight shifts, opposite arm/leg swing, restrained lag in hair tips, no changes in torso or limb length. Last pose leads continuously to pose0.'
    flaps='Four wing poses in this order: 0 wings lifted high, 1 wings extended approximately level, 2 wings swept downward, 3 wings folded slightly near lower body at bottom of downstroke. Playback goes 0,1,2,3,2,1 and loops. Both near and far wings follow the same stroke phase, side far wing may be partly occluded; front/rear wings remain clearly paired. Body never squash-stretches or turns between frames.'
    jobs=[]
    def add(key,folder,prompt,refs,cols,rows,kind,direction=None):
        (folder/'prompts').mkdir(parents=True,exist_ok=True)
        (folder/'source').mkdir(parents=True,exist_ok=True)
        prompt+='\nStyle: clean hand-drawn 2D cel shading exactly matching reference, no 3D render. Genuinely transparent RGBA background, no checkerboard, shadows, glow, labels, grid or text. Complete isolated characters, generous margins and clear gap between every cell, no overlap. EXACT specified grid and count; identical physical scale, baseline and camera within a sheet.'
        (folder/'prompts'/f'{key}.txt').write_text(prompt+'\n')
        jobs.append(dict(key=key,folder=str(folder.relative_to(ROOT)),prompt=str((folder/'prompts'/f'{key}.txt').relative_to(ROOT)),
                         source=str((folder/'source'/f'{key}.png').relative_to(ROOT)),references=refs,columns=cols,rows=rows,kind=kind,direction=direction))
    xr=['Art/NPCs/xiya/v1/static/field-front.png','Art/NPCs/xiya/v1/static/field-back.png','Art/NPCs/xiya/v1/original-reference.png']
    qr=['Art/Companions/qibei/v1/static/field-front.png','Art/Companions/qibei/v1/static/field-left.png','Art/Companions/qibei/v1/static/field-back.png']
    for direction,view in [('down','front, walking toward camera; anatomical left foot appears on viewer right'),('left','left side, facing screen LEFT, near and far limbs retain their identities'),('right','right side, facing screen RIGHT, KEEP anatomical hair parting and cap, not a mirror of left'),('up','rear view, walking away, no eyes or face on the rear')]:
        add('field-walk-'+direction,XI,'Asset: Xiya Q overworld walking atlas. '+xiya+' Match reference Q ratio: oversized head about half total height, very short torso/legs, boots not lengthened. Three columns by TWO rows = exactly SIX sequential full-body poses, row-major. Camera: '+view+'. '+walk,xr,3,2,'xiya_field_walk',direction)
    add('field-turns',XI,'Asset: Xiya Q idle side views. '+xiya+' Match original Q body ratio. Exactly TWO depictions in ONE horizontal row: LEFT cell idle facing screen LEFT; RIGHT cell idle facing screen RIGHT. Standing calmly with BOTH feet side by side, arms relaxed. Preserve anatomical hair parting/cap structure across views; do not simply mirror a new fringe. Same height and shoulder/waist/boot landmarks as v1 Q front/back.',xr,2,1,'xiya_field_idle')
    for direction,view in [('down','front'),('left','left side, facing screen LEFT'),('up','rear, no face visible')]:
        add('field-flap-'+direction,QI,'Asset: Qibei Q overworld hovering/flapping atlas. '+qibei+' Exactly FOUR independent drawings in TWO columns by TWO rows, row-major. Fixed camera '+view+'. '+flaps,qr,2,2,'qibei_field',direction)
    br=['Art/NPCs/xiya/v2/source/battle-body.png','Art/NPCs/xiya/v1/static/portrait.png']
    add('battle-idle',XI,'Asset: Xiya larger battle-body idle loop. '+xiya+' Preserve the new full-body starting pose EXACTLY: approximately six-head-tall adult proportions, not Q, hair to upper back, green mid-calf boots, stance/empty anatomical RIGHT fist and LEFT relaxed hand stay the same. Four drawings in 2x2 grid, row-major: 0 relaxed exhale,1 start small inhale,2 peak small inhale,3 release. Head/face stable, tiny chest/shoulder motion with delayed hair tips, feet planted. No whole-body rocking or posture redesign.',br,2,2,'xiya_battle_idle')
    add('battle-slash',XI,'Asset: Xiya EMPTY-HAND sword-slash body keyframes; an independent sword will be attached at runtime. '+xiya+' Approximately six heads tall exactly matching battle reference, never chibi. Exactly SIX full-body drawings in 3 columns x 2 rows, row-major. SAME anatomical RIGHT closed fist grips the future sword throughout, LEFT hand free: 0 ready stance identical reference;1 wind up, right closed fist raised beside/above head to viewer LEFT;2 commence diagonal downward slash, right fist moving forward from upper left, left arm counterbalances;3 impact, torso rotates slightly forward and right closed fist moves across to viewer RIGHT waist height, bent knees;4 follow-through, right arm extends diagonally down toward viewer RIGHT, body still balanced;5 recover right closed fist back to original viewer LEFT hip ready stance. Real shoulder/elbow/wrist changes, modest planted-foot weight transfer, no new costume or shoes, no weapon/trails in pictures. Keep right hand physically connected and body/leg lengths fixed. Frame5 leads back to frame0.',br,3,2,'xiya_battle_slash')
    add('battle-hurt',XI,'Asset: Xiya battle hurt/recover bodies. '+xiya+' Preserve adult full-body reference proportions. Exactly TWO full-body poses in ONE row:0 brief controlled recoil, shoulders pull back, left hand near chest, right fist still grips future weapon at own right hip, knees flex, face winces;1 recover toward original ready stance. No falls, flying, damage wounds, missing limbs or equipment.',br,2,1,'xiya_battle_hurt')
    add('sword',XI,'Asset: ONE neutral modular 2D sword, separate from Xiya body. Original sword type is not known; this is a review prototype. Upright straight narrow silver double-edged blade, simple small steel crossguard, charcoal wrapped one-hand grip and small steel pommel. Blade points vertically UP, grip at bottom, clean front view, perfectly straight centerline. Simple practical RPG sword, no magic effects, jewels or ornate fantasy decorations. One sword only; entire blade, hilt and pommel visible. Same restrained cel-shaded rendering as body reference.',br[:1],1,1,'sword')
    add('battle-hover',QI,'Asset: Qibei larger battle illustration, identity from v1 PORTRAIT, not field face. Input1 portrait locks pale blush-white inner face and pink outer round body, large BLUE open eyes, pink oval cheeks, small gray smiling mouth and curled pink crown tuft. Input2 field front supplies matching PAIR of pink two-lobed wings; use those wings on both sides for full-body battle form. No green cheeks or sleepy black eyes in this form. Exactly FOUR poses in 2 columns x2 rows, row-major. '+flaps+' Full round legless body, no feet or arms, same body proportions and facial locations each frame. Eyes remain blue/open across wing poses. Outer pink, face pale white, no added cat ears or furry tail.',
        ['Art/Companions/qibei/v1/static/portrait.png','Art/Companions/qibei/v1/static/field-front.png'],2,2,'qibei_battle')
    (XI/'motion-jobs.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n')
    print('Prepared',len(jobs),'motion/reference generation jobs')


if __name__=='__main__': main()
